mapper.select:
SELECT c.id, c.no, c.status, c.product_line, c.need_date, c.create_by, c.create_time,
       COALESCE(agg.buy_count, 0) AS buy_count, COALESCE(agg.converted_count, 0) AS converted_count,
       nx.id AS next_calc_id, nx.no AS next_calc_no
FROM mrp_calc c
LEFT JOIN LATERAL (SELECT COUNT(*) FILTER (WHERE i.suggest_qty > 0) AS buy_count,
                          COUNT(*) FILTER (WHERE i.suggest_qty > 0 AND i.converted_qty >= i.suggest_qty) AS converted_count
                   FROM mrp_calc_item i WHERE i.calc_id = c.id AND i.block = 'PURCHASE') agg ON true
LEFT JOIN LATERAL (SELECT n.id, n.no FROM mrp_calc n
                   WHERE n.prev_calc_id = c.id AND n.status IN ('DRAFT', 'CONFIRMED')
                   ORDER BY n.id DESC LIMIT 1) nx ON true
WHERE true
AND c.product_line = ANY(#{scope.lines.values, typeHandler=com.lingmao.scm.common.mybatis.StringArrayTypeHandler})
AND c.create_by = #{scope.userId}

    AND c.status IN #{s}

AND c.create_by = #{q.createBy}

    AND c.id IN #{id}

AND c.create_time >= (CAST(#{q.createDateFrom} AS date)::timestamp AT TIME ZONE 'Asia/Shanghai')
AND c.create_time < ((CAST(#{q.createDateTo} AS date) + 1)::timestamp AT TIME ZONE 'Asia/Shanghai')


    AND c.id IN (
        SELECT kc.id FROM mrp_calc kc WHERE upper(kc.no) LIKE #{keywordCode}

            OR upper(kc.no) IN #{code}

        UNION
        SELECT co.calc_id FROM ord_order ko JOIN mrp_calc_order co ON co.order_id = ko.id
        WHERE upper(ko.no) LIKE #{keywordCode}

            OR upper(ko.no) IN #{code}

        UNION
        SELECT co.calc_id FROM sty_style ks JOIN ord_order_item ki ON ki.style_id = ks.id
        JOIN mrp_calc_order co ON co.order_id = ki.order_id
        WHERE upper(ks.code) LIKE #{keywordCode}

            OR upper(ks.code) IN #{code}

    )

ORDER BY c.id DESC

SELECT o.id AS order_id, o.company_id, o.no AS order_no, o.order_type, o.product_line, o.total_qty, o.commit_date
FROM ord_order o
WHERE o.status IN ('APPROVED', 'RUNNING')
AND o.product_line = ANY(#{lines.values, typeHandler=com.lingmao.scm.common.mybatis.StringArrayTypeHandler})


    AND o.id IN (
        SELECT ko.id FROM ord_order ko WHERE upper(ko.no) LIKE #{keywordCode}

            OR upper(ko.no) IN #{code}

        UNION
        SELECT ki.order_id FROM sty_style ks JOIN ord_order_item ki ON ki.style_id = ks.id
        WHERE upper(ks.code) LIKE #{keywordCode}

            OR upper(ks.code) IN #{code}

    )

ORDER BY o.order_date DESC, o.no DESC
